const html = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"A small, private place to make a report for the things you miss.\"><meta name=\"theme-color\" content=\"#e7c5a8\"><title>The Lost & Found Department</title><style>\n:root{color-scheme:light;--ink:#482b29;--muted:#785b54;--blue:#566f8e;--paper:#fff6e7;--glass:rgba(252,225,210,.76);--accent:#cf622d;--shadow:0 16px 48px #422a2b38}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);font-family:Georgia,serif;background:#b98a76;min-height:100vh}body:before{content:\"\";position:fixed;inset:0;z-index:-2;background:linear-gradient(#4b364420,#51332755),url(data:image/webp;base64,) center/cover no-repeat;transition:filter .4s}body.evening:before{filter:brightness(.7) saturate(.9)}body:after{content:\"✦                 ✦\";position:fixed;top:8px;left:5%;right:5%;z-index:-1;color:#ffe5a0;text-shadow:0 0 18px #ffd16c;font-size:36px;display:flex;justify-content:space-between;pointer-events:none}.site-header{text-align:center;padding:28px 16px 20px}.sign{display:inline-block;background:#f9e5ce;border:1px solid #765249;outline:3px double #805e54;outline-offset:-9px;padding:17px 48px;box-shadow:0 6px 16px #3d242640}.sign h1{font-size:clamp(1.45rem,3vw,2.5rem);letter-spacing:.1em;text-transform:uppercase;margin:0}.sign p{font-style:italic;margin:7px 0 0;font-size:1.05rem}.shell{max-width:1360px;margin:0 auto 30px;padding:0 22px}.window{border:1px solid #fff9e7;border-radius:22px;background:linear-gradient(135deg,#f8e4d6cd,#d6a9a6b8);box-shadow:var(--shadow),inset 0 1px #fff9;backdrop-filter:blur(14px);overflow:hidden}.titlebar{height:46px;border-bottom:1px solid #fff8;display:flex;align-items:center;justify-content:space-between;padding:0 22px;color:#5e3934;letter-spacing:.08em;font-size:.75rem;text-transform:uppercase}.dots{font-size:1.1rem;letter-spacing:5px}.content{display:grid;grid-template-columns:minmax(300px,.82fr) minmax(0,1.18fr);gap:28px;padding:28px;align-items:start}.form-panel{border:1px solid #fff5e8;border-radius:18px;padding:28px;background:#fbe9dda8}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font:700 .69rem system-ui,sans-serif;color:var(--blue)}h2{font-size:clamp(1.6rem,2.1vw,2rem);margin:9px 0 8px;line-height:1.15}p{line-height:1.5}.intro{color:var(--muted);margin:0 0 23px;font-size:.94rem}.form-rule{border:0;border-top:1px solid #ac8276;margin:20px 0}label{display:block;font-weight:bold;font-size:.97rem;margin:16px 0 7px}label span{color:#826860;font-weight:normal;font-size:.8rem}input,textarea{font:1rem Georgia,serif;width:100%;border:1px solid #b58c7e;border-radius:9px;padding:12px 13px;background:#fff9eddd;color:var(--ink)}textarea{resize:vertical;min-height:74px}input::placeholder,textarea::placeholder{color:#967e73}button,a{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #466a91;outline-offset:3px}.primary{width:100%;background:linear-gradient(#e17a40,#c95829);border:1px solid #a94422;border-radius:11px;color:#fffaf1;font-size:1.1rem;font-weight:bold;padding:14px;margin-top:20px;box-shadow:0 4px 0 #9f4a2b55}.primary:hover{filter:brightness(1.06)}.privacy{font: .77rem/1.5 system-ui,sans-serif;color:#725951;margin:17px 0 0}.report-area{min-width:0}.report-label{display:flex;justify-content:space-between;align-items:center;margin:0 4px 12px;font:700 .7rem system-ui;letter-spacing:.14em;text-transform:uppercase;color:#644e49}.paper-stack{position:relative;padding:8px 10px 12px}.paper-stack:before,.paper-stack:after{content:\"\";position:absolute;inset:10px;background:#dfbf98;border-radius:5px;box-shadow:0 4px 10px #5e382d38;transform:rotate(2deg)}.paper-stack:after{transform:rotate(-2deg);background:#e8d3b0}.paper{position:relative;z-index:1;background:radial-gradient(circle at 30% 20%,#fffaf0,#f8ead5 80%);border:1px solid #b9957c;outline:3px double #c4a38e;outline-offset:-12px;min-height:465px;padding:37px clamp(25px,5vw,60px);box-shadow:0 9px 20px #593b2c30;overflow-wrap:anywhere}.paper-header{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;border-bottom:3px double #9e7868;padding-bottom:15px}.paper-kicker{font:700 .65rem system-ui;letter-spacing:.15em;text-transform:uppercase;color:#786258}.paper h3{text-transform:uppercase;letter-spacing:.12em;margin:6px 0 0;font-size:clamp(1.15rem,2.1vw,1.7rem)}.stamp{border:2px double var(--blue);color:var(--blue);border-radius:50%;width:78px;height:78px;flex:none;display:grid;place-items:center;text-align:center;font:700 .55rem/1.3 system-ui;transform:rotate(12deg);letter-spacing:.09em}.stamp b{display:block;font-size:1.3rem}.paper-meta{display:flex;gap:20px;justify-content:space-between;color:#8a6c61;font: .68rem system-ui;letter-spacing:.06em;margin-top:15px}.report-title{font-size:clamp(1.8rem,3vw,2.6rem);line-height:1.14;font-style:italic;margin:26px 0 18px}.entry{margin:18px 0}.entry strong{display:block;color:var(--blue);font:700 .65rem system-ui;letter-spacing:.13em;text-transform:uppercase;margin-bottom:6px}.entry p{white-space:pre-wrap;margin:0;line-height:1.45}.status{background:#d6dde3aa;border:1px solid #8ca0b4;color:#475d76;padding:12px;text-align:center;font-style:italic;font-size:1.1rem;margin-top:25px}.empty{text-align:center;color:#7d685d;padding:48px 10px 22px}.empty-icon{font-size:3rem;color:#7087a2}.empty h4{font-size:1.4rem;margin:10px 0}.empty p{max-width:290px;margin:0 auto}.actions{display:flex;flex-wrap:wrap;gap:9px;justify-content:center;margin:19px 0 2px}.secondary{border:1px solid #b38c7e;background:#fff4e5;color:#553b35;border-radius:9px;padding:10px 16px;font-weight:bold}.secondary:hover{background:#fffaf2}.window-footer{text-align:center;border-top:1px solid #fff9;padding:16px;font-style:italic;font-size:.88rem}.office{margin:24px 0;background:#f8e5d8dd;border:1px solid #fff2e5;border-radius:20px;padding:28px;box-shadow:var(--shadow)}.clerk{width:110px;height:110px;flex:none;border:3px solid #f3dfc8;border-radius:50%;background:url(data:image/webp;base64,) 81% 63% / 650% auto;box-shadow:0 3px 10px #684a3b55}.office-head{display:flex;justify-content:space-between;align-items:end;gap:20px}.office h2{margin:5px 0}.office p{color:var(--muted)}.office-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:20px}.object{border:1px solid #cba899;border-radius:12px;background:#fff7eac9;padding:20px;text-align:left;color:var(--ink);min-height:130px}.object:hover{transform:translateY(-2px);background:#fff8ec}.object .icon{font-size:1.7rem;display:block;margin-bottom:10px}.object strong{font-size:1.1rem;display:block}.object small{display:block;font: .78rem/1.5 system-ui;color:#80685d;margin-top:7px}.sister{border-top:1px solid #c5a59a;margin-top:22px;padding-top:18px;font-size:.9rem;color:#775b53}.sister b{color:#4b6179}.modal{border:1px solid #a98578;border-radius:18px;background:#fff5e5;color:var(--ink);max-width:520px;width:calc(100% - 30px);padding:30px;box-shadow:var(--shadow)}.modal::backdrop{background:#3d292baa}.modal h2{margin-top:0}.modal .close{float:right}.samples{display:grid;gap:10px}.sample{padding:12px;border:1px solid #d3b6a5;background:#f9ebda;border-radius:8px}.sample b{display:block}.sample small{color:#806960}.foot{text-align:center;color:#fff5e5;font: .75rem system-ui;padding:5px 0 25px;text-shadow:0 1px 3px #503028}[hidden]{display:none!important}@media(max-width:800px){.content{grid-template-columns:1fr;padding:17px}.office-grid{grid-template-columns:1fr}.sign{padding:16px 25px}.site-header{padding-top:18px}.shell{padding:0 12px}.paper{min-height:400px}.office-head{display:block}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}@media print{body{background:white!important}body:before,body:after,.site-header,.titlebar,.form-panel,.report-label,.actions,.window-footer,.office,.foot{display:none!important}.shell,.content{display:block;margin:0;padding:0;max-width:none}.window{border:0;box-shadow:none;background:none;overflow:visible}.paper-stack{padding:0}.paper-stack:before,.paper-stack:after{display:none}.paper{box-shadow:none;min-height:0;break-inside:auto}.report-area{display:block}}\n</style></head><body><header class=\"site-header\"><div class=\"sign\"><h1>The Lost &amp; Found Department</h1><p>A place for the things you miss.</p></div></header><main class=\"shell\"><section class=\"window\" aria-label=\"Lost item report\"><div class=\"titlebar\"><span>✦ &nbsp; The department is open</span><span class=\"dots\" aria-hidden=\"true\">− □ ×</span></div><div class=\"content\"><section class=\"form-panel\"><div class=\"eyebrow\">Department of small &amp; important things</div><h2>Report something lost</h2><p class=\"intro\">Some things are hard to name. Take your time; there’s no wrong way to begin.</p><hr class=\"form-rule\"><form id=\"form\"><label for=\"lost\">What did you lose? <span>(required)</span></label><input id=\"lost\" name=\"lost\" required maxlength=\"180\" placeholder=\"A feeling, a dream, a little piece of something…\"><label for=\"when\">When do you remember last having or feeling it? <span>(optional)</span></label><textarea id=\"when\" name=\"when\" maxlength=\"800\" placeholder=\"A moment, a season, or whenever comes to mind\"></textarea><label for=\"miss\">What do you miss about it? <span>(optional)</span></label><textarea id=\"miss\" name=\"miss\" maxlength=\"800\" placeholder=\"Anything you’d like to remember\"></textarea><label for=\"note\">A note to yourself <span>(optional)</span></label><textarea id=\"note\" name=\"note\" maxlength=\"800\" placeholder=\"A few words for yourself, if you’d like\"></textarea><button class=\"primary\" type=\"submit\">Create my report &nbsp; →</button></form><p class=\"privacy\">🔒 Your words stay in this browser tab. No account, uploads, or AI. Reloading or closing the page may clear your report.</p></section><section class=\"report-area\" aria-label=\"Report preview\"><div class=\"report-label\"><span>Your report preview</span><span>Form no. 001 ✦</span></div><div class=\"paper-stack\"><article class=\"paper\" id=\"paper\" aria-live=\"polite\"><div class=\"paper-header\"><div><div class=\"paper-kicker\">The Lost &amp; Found Department</div><h3>Lost Item Report</h3></div><div class=\"stamp\" aria-label=\"Department stamp\"><div>LOST &amp; FOUND<b>✦</b>DEPARTMENT</div></div></div><div id=\"empty\" class=\"empty\"><div class=\"empty-icon\" aria-hidden=\"true\">✧</div><h4>A little space for what you miss.</h4><p>Your report will appear here when you’re ready to make one.</p></div><div id=\"report\" hidden><div class=\"paper-meta\"><span id=\"case\"></span><span id=\"date\"></span></div><h4 class=\"report-title\" id=\"result-lost\"></h4><div id=\"result-fields\"></div><div class=\"status\">We’re keeping an eye out.</div></div></article></div><div id=\"actions\" class=\"actions\" hidden><button class=\"secondary\" id=\"edit\" type=\"button\">✎ Edit report</button><button class=\"secondary\" id=\"download\" type=\"button\">↓ Download PNG</button><button class=\"secondary\" id=\"print\" type=\"button\">⎙ Print</button><button class=\"secondary\" id=\"reset\" type=\"button\">Start over</button></div><p id=\"notice\" class=\"privacy\" role=\"status\"></p></section></div><div class=\"window-footer\">✧ &nbsp; A gentle reminder: you don’t have to have it all figured out. &nbsp; ✧</div></section><section class=\"office\" id=\"office\"><div class=\"office-head\"><div><div class=\"eyebrow\">A little further in</div><h2>Look around the office</h2><p>There’s room to linger, if you’d like.</p></div><div class=\"clerk\" role=\"img\" aria-label=\"The department clerk, smiling at the desk\"></div></div><div class=\"office-grid\"><button class=\"object\" id=\"cabinet\"><span class=\"icon\" aria-hidden=\"true\">🗄️</span><strong>The filing cabinet</strong><small>Peek at a few fictional reports.</small></button><button class=\"object\" id=\"desk\"><span class=\"icon\" aria-hidden=\"true\">✉️</span><strong>A note from the desk</strong><small>A little about this place.</small></button><button class=\"object\" id=\"lamp\" aria-pressed=\"false\"><span class=\"icon\" aria-hidden=\"true\">💡</span><strong>The desk lamp</strong><small id=\"lamp-label\">Switch to evening light.</small></button></div><div class=\"sister\"><span class=\"eyebrow\">Sister department</span><br><b>The Department of Unfinished Things</b> &nbsp;·&nbsp; A neighboring office, opening another day.</div></section><div class=\"foot\">A fictional department, made for real feelings. ✦</div></main><dialog class=\"modal\" id=\"cabinet-dialog\"><button class=\"secondary close\" data-close>Close</button><div class=\"eyebrow\">Filing cabinet · fictional examples</div><h2>A few things on file</h2><p>These are imagined examples, here to welcome you in.</p><div class=\"samples\"><div class=\"sample\"><b>A sense of wonder</b><small>Fictional sample · last noticed on a long walk</small></div><div class=\"sample\"><b>The courage to begin</b><small>Fictional sample · last noticed on a Monday morning</small></div><div class=\"sample\"><b>Unhurried afternoons</b><small>Fictional sample · last noticed one summer</small></div></div></dialog><dialog class=\"modal\" id=\"desk-dialog\"><button class=\"secondary close\" data-close>Close</button><div class=\"eyebrow\">A note from the desk</div><h2>Dear visitor,</h2><p>This is a fictional little office for the things that can be difficult to hold, but still matter. Making a report is a way to give those things a little space.</p><p>There’s no investigation behind the scenes, and no one else receives your words. The report is yours to keep, print, or simply leave here.</p><p>We’re glad you stopped by.<br><em>— The clerk</em> ✦</p></dialog><script>\nconst $=s=>document.querySelector(s), form=$('#form'); let current=null; const fields=['lost','when','miss','note']; const labels={when:'Last remembered',miss:'What I miss',note:'A note to myself'};\nfunction showReport(data){current=data; $('#empty').hidden=true; $('#report').hidden=false; $('#actions').hidden=false; $('#case').textContent='CASE NO. '+data.caseNo; $('#date').textContent=data.date; $('#result-lost').textContent=data.lost; const box=$('#result-fields');box.replaceChildren(); for(const key of ['when','miss','note']){if(!data[key])continue;const div=document.createElement('div'); div.className='entry';const heading=document.createElement('strong');heading.textContent=labels[key];const p=document.createElement('p');p.textContent=data[key];div.append(heading,p);box.append(div)}}\nform.addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(fields.map(k=>[k,form.elements[k].value.trim()]));if(!values.lost){form.elements.lost.value='';form.elements.lost.focus();form.reportValidity();return}const old=current;showReport({...values,caseNo:old?.caseNo||('LF-'+Math.random().toString(36).slice(2,8).toUpperCase()),date:old?.date||new Date().toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'})});$('#notice').textContent='Your report is ready.';if(matchMedia('(max-width: 800px)').matches)$('#paper').scrollIntoView({behavior:'smooth',block:'start'})});\n$('#edit').onclick=()=>{form.elements.lost.focus();form.scrollIntoView({behavior:'smooth',block:'start'})};$('#reset').onclick=()=>{form.reset();current=null;$('#empty').hidden=false;$('#report').hidden=true;$('#actions').hidden=true;$('#notice').textContent='Your report has been cleared.';form.elements.lost.focus()};$('#print').onclick=()=>window.print();\n$('#lamp').onclick=()=>{const on=document.body.classList.toggle('evening');$('#lamp').setAttribute('aria-pressed',String(on));$('#lamp-label').textContent=on?'Switch to daytime light.':'Switch to evening light.'};for(const id of ['cabinet','desk'])$('#'+id).onclick=()=>$('#'+id+'-dialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());\n// Draw a self-contained, full-length report, expanding the canvas for long answers.\n$('#download').onclick=()=>{if(!current)return;try{const width=1400,margin=125,available=width-margin*2;const measure=document.createElement('canvas').getContext('2d');function wrap(text,font){measure.font=font;const out=[];for(const paragraph of text.split('\\n')){let line='';for(const word of paragraph.split(/\\s+/)){if(!word)continue;let pieces=[word];if(measure.measureText(word).width>available){pieces=[];let part='';for(const ch of word){if(part&&measure.measureText(part+ch).width>available){pieces.push(part);part=''}part+=ch}if(part)pieces.push(part)}for(const piece of pieces){const next=line?line+' '+piece:piece;if(measure.measureText(next).width>available&&line){out.push(line);line=piece}else line=next}}out.push(line)}return out}const title=wrap(current.lost,'italic 64px Georgia');const entries=['when','miss','note'].filter(k=>current[k]).map(k=>({label:labels[k],lines:wrap(current[k],'32px Georgia')}));let height=490+title.length*78+entries.reduce((s,e)=>s+75+e.lines.length*48,0)+170;const c=document.createElement('canvas');c.width=width;c.height=height;const x=c.getContext('2d');x.fillStyle='#f8ecd9';x.fillRect(0,0,width,height);x.strokeStyle='#a48773';x.lineWidth=3;x.strokeRect(25,25,width-50,height-50);x.lineWidth=1;x.strokeRect(38,38,width-76,height-76);x.fillStyle='#765d50';x.font='bold 20px sans-serif';x.fillText('THE LOST & FOUND DEPARTMENT',margin,105);x.fillStyle='#482b29';x.font='bold 44px Georgia';x.fillText('LOST ITEM REPORT',margin,170);x.strokeStyle='#9a7867';x.beginPath();x.moveTo(margin,200);x.lineTo(width-margin,200);x.stroke();x.fillStyle='#647d98';x.font='bold 19px sans-serif';x.fillText('✦  DEPARTMENT RECORD',margin,245);x.fillStyle='#80675c';x.font='20px sans-serif';x.fillText('CASE NO. '+current.caseNo,margin,290);x.textAlign='right';x.fillText(current.date,width-margin,290);x.textAlign='left';let y=370;x.fillStyle='#482b29';x.font='italic 64px Georgia';for(const line of title){x.fillText(line,margin,y);y+=78}for(const entry of entries){y+=20;x.fillStyle='#627c96';x.font='bold 19px sans-serif';x.fillText(entry.label.toUpperCase(),margin,y);y+=40;x.fillStyle='#482b29';x.font='32px Georgia';for(const line of entry.lines){x.fillText(line,margin,y);y+=48}}y+=30;x.fillStyle='#dce2e4';x.fillRect(margin,y,available,76);x.strokeStyle='#91a4b6';x.strokeRect(margin,y,available,76);x.fillStyle='#465e77';x.textAlign='center';x.font='italic 32px Georgia';x.fillText('We’re keeping an eye out.',width/2,y+49);const a=document.createElement('a');a.download='lost-item-report.png';a.href=c.toDataURL('image/png');a.click();$('#notice').textContent='Your PNG is ready.'}catch(err){$('#notice').textContent='Could not create the image. Try printing your report instead.'}};\n</script></body></html>\n";
export default { fetch(request) { if (new URL(request.url).pathname !== '/') return new Response('Not found', {status:404}); return new Response(html, {headers: {'content-type':'text/html; charset=utf-8','x-content-type-options':'nosniff','referrer-policy':'no-referrer'}}); } };
